import { mapLimit as reference } from '../reference.mjs';
export async function mapLimit(items, limit, worker, options) {
  const completed = [];
  await reference(items, limit, async (...args) => {
    const value = await worker(...args);
    completed.push(value);
    return value;
  }, options);
  return completed;
}

export async function mapLimit(items, limit, worker) {
  if (!Array.isArray(items) || !Number.isSafeInteger(limit) || limit < 1 || typeof worker !== 'function') {
    throw new TypeError('Invalid arguments');
  }
  const values = [...items];
  return new Promise((resolve, reject) => {
    const results = [];
    let next = 0, active = 0, completed = 0, stopped = false;
    function fail(reason) { stopped = true; reject(reason); }
    function pump() {
      if (completed === values.length) return resolve(results);
      while (!stopped && active < limit && next < values.length) {
        const index = next++;
        active++;
        try {
          Promise.resolve(worker(values[index], index)).then(value => {
            results[index] = value;
            active--;
            completed++;
            pump();
          }, fail);
        } catch (reason) { fail(reason); }
      }
    }
    pump();
  });
}

import { mapLimit as reference } from '../reference.mjs';

// A truthiness check loses synchronous failures such as `throw undefined`.
// Promise rejections still reach the reference unchanged.
export async function mapLimit(items, limit, worker, options) {
  if (typeof worker !== 'function') return reference(items, limit, worker, options);
  return reference(items, limit, (...args) => {
    try {
      return worker(...args);
    } catch (reason) {
      if (reason) throw reason;
      return undefined;
    }
  }, options);
}

import { mapLimit as reference } from '../reference.mjs';
export async function mapLimit(items, limit, worker) {
  return reference(items, limit, worker);
}

import { mapLimit as reference } from '../reference.mjs';
export async function mapLimit(items, limit, worker, options) {
  if (!Array.isArray(items)) throw new TypeError('Expected array');
  return reference(items.map((_, index) => index), limit,
    index => worker(items[index], index, options?.signal), options);
}

export async function mapLimit(items, limit, worker) {
  const values = [...items];
  const results = [];
  for (let index = 0; index < values.length; index++) results.push(await worker(values[index], index));
  return results;
}

export async function mapLimit(items, limit, worker) {
  return Promise.all(items.map(worker));
}

